package com.vynedam.stockai.config;
import com.vynedam.stockai.security.JwtAuthenticationFilter; import java.util.List; import org.springframework.beans.factory.annotation.Value; import org.springframework.context.annotation.*; import org.springframework.http.HttpMethod; import org.springframework.security.config.annotation.method.configuration.EnableMethodSecurity; import org.springframework.security.config.annotation.web.builders.HttpSecurity; import org.springframework.security.config.http.SessionCreationPolicy; import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.security.web.*; import org.springframework.security.web.authentication.UsernamePasswordAuthenticationFilter; import org.springframework.web.cors.*;
@Configuration @EnableMethodSecurity public class SecurityConfig { private final JwtAuthenticationFilter jwt; public SecurityConfig(JwtAuthenticationFilter j){jwt=j;} @Bean SecurityFilterChain security(HttpSecurity h)throws Exception{return h.csrf(c->c.disable()).cors(c->{}).httpBasic(c->c.disable()).formLogin(c->c.disable()).sessionManagement(s->s.sessionCreationPolicy(SessionCreationPolicy.STATELESS)).authorizeHttpRequests(a->a.requestMatchers("/api/v1/health","/api/v1/auth/**","/actuator/health/**").permitAll().anyRequest().authenticated()).addFilterBefore(jwt,UsernamePasswordAuthenticationFilter.class).build();} @Bean PasswordEncoder passwords(){return new BCryptPasswordEncoder(12);}@Bean CorsConfigurationSource cors(@Value("${app.cors-origin}")String origin){var c=new CorsConfiguration();c.setAllowedOrigins(List.of(origin.split(",")));c.setAllowedMethods(List.of("GET","POST","PUT","PATCH","DELETE","OPTIONS"));c.setAllowedHeaders(List.of("Authorization","Content-Type"));var s=new UrlBasedCorsConfigurationSource();s.registerCorsConfiguration("/**",c);return s;} }
